local pvpArenaComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PVPArenaComponent)
---@type TeamComponent
local teamComponent        = GameUtils.GetEntityCompByType(ECSComponentType.Constants.TeamComponent)
------------ import ------------

------------ define ------------
local PVPArenaId = Constants.SpecialQuestId.PVPArenaId
