------------ define ------------

function PVPArenaFormationDialog:__init()
    self._allTeamPosInfoGo = {}
end

function PVPArenaFormationDialog:__delete()
    self.anchoredPositions = nil
end

function PVPArenaFormationDialog:Awake()
    PVPArenaUtils.RefreshCommonUITitleNode(self.CommonUITitleNode.gameObject, localize("队伍编辑"))
    --------------------------------
    --- 初始化数据
    ---@type PVPArenaEntryDojo
    self.pvpArenaEntryDojo = pvpArenaComponent:GetPVPArenaEntryDojo()
    self.teamStatus        = {}
    self.anchoredPositions = {}
    local teamCount = pvpArenaComponent:GetTeamNumbers()
    for i = 1, teamCount do
        ---@type UnityEngine.RectTransform
        local team = self[string.format("Team%s", i)]
        self.teamStatus[i]        = teamComponent:CheckTeamInfoIsHaveEmptyNode(PVPArenaId, i)
        self.anchoredPositions[i] = team.position
    end

    --------------------------------
    --- 初始化事件监听
    self.listenerConf = {
        [Constants.EventNames.PVPArenaRefreshTeamMember] = Bind(self, self.EventRefreshTeamMember),
        [Constants.EventNames.PVPArenaRequestHomeSuccess] = Bind(self, self.EventRequestHomeSuccess),
        [Constants.EventNames.PVPArenaFormationInfoNodeEndDrag] = Bind(self, self.EventFormationInfoNodeEndDrag),
        [Constants.EventNames.RefeshTeamMember] = Bind(self, self.OnEventRefreshTeamMember),
        [Constants.EventNames.SkillCompoundChange] = Bind(self, self.OnEventSkillCompoundChange),

    }
    for listenerKey, func in pairs(self.listenerConf) do
        Events.AddListener(listenerKey, func)
    end

    --------------------------------
    --- 初始化按钮监听
    UIEventProxy.Create(self.BtnFight.gameObject).onPointerClick = Bind(self, self.OnClickBtnSaveTeamAction)
    UIEventProxy.Create(self.BtnCloseArea.gameObject).onPointerClick = Bind(self, self.OnClickBtnCloseAreaAction)
    UIEventProxy.Create(self.BtnOneKeyTeamSetting.gameObject).onPointerClick = Bind(self, self.OnClickBtnOneKeyTeamSettingAction)

    self.BtnFightText.text = localize("保存编队")
end

