function PVPArenaFormationDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self:CreateCountdownEvent()
            self:RefreshUI()
        end)
    end))
    return coWait
end

function PVPArenaFormationDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        for listenerKey, func in pairs(self.listenerConf) do
            Events.RemoveListener(listenerKey, func)
            func = nil
        end
        self.listenerConf = nil

        self:RemoveCountdownEvent()

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function PVPArenaFormationDialog:CreateCountdownEvent()
    if self.__EventCountDownUpdate then return end

    self.__EventCountDownUpdate = Events.AddListener(Constants.EventNames.PVPArenaCountDownUpdate, Bind(self, self.OnEventCountDownUpdate))
end

function PVPArenaFormationDialog:RemoveCountdownEvent()
    if self.__EventCountDownUpdate then
        Events.RemoveListener(Constants.EventNames.PVPArenaCountDownUpdate, self.__EventCountDownUpdate)
        self.__EventCountDownUpdate = nil
    end
end

