function PVPArenaFormationDialog:RefreshUI()
    self:RefreshButtonText()
    self:RefreshAllFormationInfo()

    self:RefreshCountdownEvent()
end

function PVPArenaFormationDialog:RefreshButtonText()
    local isShowResetBtn = self:GetIsShowResetBtn()
    local buttonText = isShowResetBtn and localize("重置") or localize("一键编队")
    self.BtnOneKeyTeamSettingText.text = buttonText

end

---RefreshAllFormationInfo
---刷新所有的编队信息
function PVPArenaFormationDialog:RefreshAllFormationInfo()
    local teamCount = pvpArenaComponent:GetTeamNumbers()
    for i = 1, teamCount do
        ---@type UnityEngine.RectTransform
        local team = self[string.format("Team%s", i)]
        self:RefreshFormationInfo(team.gameObject, i)
    end
end

function PVPArenaFormationDialog:RefreshFormationInfo(gameObject, index)
    ---@type PVPArenaFormationInfoNode
    local Env = CfUtils.GetLuaScr(gameObject, PVPArenaFormationInfoNodePath)
    if isNull(Env) then return end
    if index then
        Env:SetIndex(index)
        ---@type PVPArenaDojo
        local pvpArenaDojo = pvpArenaComponent:GetPVPArenaDojo()
        Env:RefreshText(pvpArenaDojo.actionOrder)
    end
    Env:RefreshUI()
end

function PVPArenaFormationDialog:RefreshCountdownEvent()
    local seconds = pvpArenaComponent:GetSeasonStageLeftSeconds()
    self.TxtTime.text = GetTimeHMS2(seconds)
end

