---GetIsShowResetBtn
---获取是否显示重置按钮
function PVPArenaFormationDialog:GetIsShowResetBtn()
    local isShowResetBtn = true
    for i, v in ipairs(self.teamStatus) do
        isShowResetBtn = isShowResetBtn and not v
    end
    return isShowResetBtn
end

