---OnEventCountDownUpdate
---事件 倒计时更新
function PVPArenaFormationDialog:OnEventCountDownUpdate()
    local pvpArenaEntryDojo = self.pvpArenaEntryDojo
    local seasonFlag = pvpArenaComponent:GetSeasonFlag()
    local offset = seasonFlag == Constants.PVPArenaSeasonFullStatus.Quiz and pvpArenaComponent:GetNoticeSecond() or 0
    local leftSeconds = pvpArenaEntryDojo.nextStageLeftSeconds + offset
    self.TxtTime.text = GetTimeHMS2(leftSeconds)
end

---EventRefreshTeamMember
---事件 刷新团队
---@param teamIndex number 团队下标
function PVPArenaFormationDialog:EventRefreshTeamMember(teamIndex)
    self.teamStatus[teamIndex] = teamComponent:CheckTeamInfoIsHaveEmptyNode(PVPArenaId, teamIndex)
    self:RefreshButtonText()
end

---EventRequestHomeSuccess
---事件 请求home 成功
function PVPArenaFormationDialog:EventRequestHomeSuccess()
    --- 刷新前两个团队的先后手
    ---@type PVPArenaDojo
    local pvpArenaDojo = pvpArenaComponent:GetPVPArenaDojo()
    local actionOrder  = pvpArenaDojo.actionOrder
    for i, v in ipairs(actionOrder) do
        ---@type UnityEngine.RectTransform
        local team = self[string.format("Team%s", i)]
        ---@type PVPArenaFormationInfoNode
        local Env = CfUtils.GetLuaScr(team.gameObject, PVPArenaFormationInfoNodePath)
        if not isNull(Env) then
            Env:RefreshText(actionOrder)
        end
    end

end

---EventFormationInfoNodeEndDrag
---事件 拖拽团队信息节点成功
---@param index number
function PVPArenaFormationDialog:EventFormationInfoNodeEndDrag(index)
    local teamCount = pvpArenaComponent:GetTeamNumbers()
    ---@type UnityEngine.RectTransform
    local dragTeam = self[string.format("Team%s", index)]
    for i = 1, teamCount do
        if index ~= i then
            ---@type UnityEngine.RectTransform
            local team = self[string.format("Team%s", i)]
            if dragTeam:Overlaps(team) then
                --- 交换数据
                teamComponent:SwapTeam(PVPArenaId, index, i)

                --- 刷新对应的节点
                self:RefreshFormationInfo(dragTeam.gameObject)
                self:RefreshFormationInfo(team.gameObject)

                break
            end
        end
    end
    local oldAnchoredPosition = self.anchoredPositions[index]
    dragTeam.position = oldAnchoredPosition

end

function PVPArenaFormationDialog:OnEventRefreshTeamMember()
    self:RefreshAllFormationInfo()
end

function PVPArenaFormationDialog:OnEventSkillCompoundChange()
    self:RefreshAllFormationInfo()
end

function PVPArenaFormationDialog:OnClickBtnCloseAreaAction()
    self:OnClickBtnSaveTeamAction()
end

function PVPArenaFormationDialog:OnClickBtnOneKeyTeamSettingAction()
    local isShowResetBtn = self:GetIsShowResetBtn()
    local teamCount = pvpArenaComponent:GetTeamNumbers()
    if isShowResetBtn then
        teamComponent:ResetAllTeam(PVPArenaId, teamCount, Constants.ChooseCardStatus.Normal)
    else
        teamComponent:PlayerOneKeyEditTeam(PVPArenaId, teamCount, Constants.ChooseCardStatus.Normal)
    end
end

function PVPArenaFormationDialog:OnClickBtnSaveTeamAction()

    teamComponent:SetTeamReq(PVPArenaId, function()
        UIModule.BackDialog()
    end)
end
